export function ArchimedLogo({ size = 28, className, tone = "brand", title = "SDAI ARCHIMED" }: Props) {
  const stroke = tone === "brand" ? "url(#archimed-brass)" : "currentColor";
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 32 32"
      role="img"
      aria-label={title}
      className={className}
    >
      {tone === "brand" && (
        <defs>
          <linearGradient id="archimed-brass" x1="0.15" y1="0.1" x2="0.85" y2="0.95">
            <stop offset="0" stopColor="#F2D58E" />
            <stop offset="0.55" stopColor="#D9A94F" />
            <stop offset="1" stopColor="#A9772E" />
          </linearGradient>
        </defs>
      )}
      <path
        d={SPIRAL}
        fill="none"
        stroke={stroke}
        strokeWidth={2.4}
        strokeLinecap="round"
        strokeLinejoin="round"
      />
      <circle cx="16" cy="16.4" r="1.5" fill={tone === "brand" ? "#F2D58E" : "currentColor"} />
    </svg>
  );
}
